from collections import deque

def transform(txt):
    a=[list(map(int,s)) for s in txt.splitlines()]; R=len(a); C=len(a[0]); seen=set(); zcomp={}; ztype={};
    # zero connected components
    for r in range(R):
      for c in range(C):
       if a[r][c]!=0 or (r,c) in seen: continue
       q=deque([(r,c)]); seen.add((r,c)); cells=[]; border=False
       while q:
        x,y=q.popleft(); cells.append((x,y)); border |= x==0 or y==0 or x==R-1 or y==C-1
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         nx,ny=x+dx,y+dy
         if 0<=nx<R and 0<=ny<C and a[nx][ny]==0 and (nx,ny) not in seen:
          seen.add((nx,ny)); q.append((nx,ny))
       for cell in cells: zcomp[cell]=len(ztype)
       ztype[len(ztype)]=('exterior' if border else 'interior',cells)
    # one comps
    seen1=set(); comps=[]; compid={}
    for r in range(R):
      for c in range(C):
       if a[r][c]!=1 or (r,c) in seen1: continue
       q=deque([(r,c)]); seen1.add((r,c)); cells=[]
       while q:
        x,y=q.popleft(); cells.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         nx,ny=x+dx,y+dy
         if 0<=nx<R and 0<=ny<C and a[nx][ny]==1 and (nx,ny) not in seen1:
          seen1.add((nx,ny));q.append((nx,ny))
       i=len(comps); comps.append(cells)
       for cell in cells: compid[cell]=i
    activated=set()
    for i,cells in enumerate(comps):
      for r,c in cells:
       for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
        nx,ny=r+dx,c+dy
        if 0<=nx<R and 0<=ny<C and a[nx][ny]==0 and ztype[zcomp[(nx,ny)]][0]=='interior': activated.add(i)
    b=[row[:] for row in a]
    for i in activated:
      for r,c in comps[i]:
       for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
        nx,ny=r+dx,c+dy
        if 0<=nx<R and 0<=ny<C and a[nx][ny]==0:
         typ=ztype[zcomp[(nx,ny)]][0]
         b[nx][ny]=3 if typ=='interior' else 2
    return b, {'comps':comps,'activated':activated,'ztype':ztype}

